"""Core tabular structures for :mod:`datalab`.

A :class:`Table` is a lightweight, dependency-free container for tabular
data.  Column names are stored separately from the row data and individual
:class:`Column` objects expose helpers used by the cleaning and analysis
modules.
"""

from __future__ import annotations

from typing import Any, Dict, Iterable, Iterator, List, Mapping, Optional, Sequence

__all__ = ["Table", "Column", "ColumnNotFoundError", "to_number", "is_missing"]


MISSING_TOKENS = frozenset({"", "na", "n/a", "nan", "null", "none", "-"})


class ColumnNotFoundError(KeyError):
    """Raised when a requested column does not exist in a table."""

    def __init__(self, name: str):
        super().__init__(name)
        self.name = name

    def __str__(self) -> str:  # pragma: no cover - cosmetic
        return f"column not found: {self.name!r}"


def is_missing(value: Any) -> bool:
    """Return ``True`` when *value* represents a missing entry.

    Missing entries are ``None`` and the common textual placeholders used in
    CSV exports (``""``, ``"NA"``, ``"N/A"``, ``"null"``, ``"none"`` and
    ``"-"``), matched case-insensitively after stripping whitespace.
    """
    if value is None:
        return True
    if isinstance(value, float) and value != value:  # NaN
        return True
    if isinstance(value, str):
        return value.strip().lower() in MISSING_TOKENS
    return False


def to_number(value: Any) -> Optional[float]:
    """Best-effort conversion of *value* to an ``int`` or ``float``.

    Returns ``None`` when the value is missing or cannot be interpreted as a
    number.  Common representations such as ``"1,234.5"``, ``"$1,234"``,
    ``"(1,200)"`` and ``"50%"`` are understood.
    """
    if value is None or isinstance(value, bool):
        if isinstance(value, bool):
            return int(value)
        return None
    if isinstance(value, (int, float)):
        if value != value:  # NaN
            return None
        return value
    if not isinstance(value, str):
        return None

    text = value.strip()
    if not text or text.lower() in MISSING_TOKENS:
        return None

    negative = text.startswith("(") and text.endswith(")")
    if negative:
        text = text[1:-1].strip()

    percent = text.endswith("%")
    if percent:
        text = text[:-1].strip()

    text = text.replace(",", "").replace("_", "")
    if text.startswith("$"):
        text = text[1:]
    if text.startswith("+"):
        text = text[1:]

    try:
        number = float(text)
    except ValueError:
        return None

    if negative:
        number = -number
    if percent:
        number /= 100.0

    if number.is_integer() and not any(c in text for c in ".eE"):
        return int(number)
    return number


class Column:
    """A single named column of values."""

    __slots__ = ("_name", "_values")

    def __init__(self, name: str, values: Iterable[Any]):
        self._name = name
        self._values: List[Any] = list(values)

    @property
    def name(self) -> str:
        return self._name

    @property
    def values(self) -> List[Any]:
        return list(self._values)

    def __iter__(self) -> Iterator[Any]:
        return iter(self._values)

    def __len__(self) -> int:
        return len(self._values)

    def __getitem__(self, index):
        return self._values[index]

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Column):
            return NotImplemented
        return self._name == other._name and self._values == other._values

    def __repr__(self) -> str:
        return f"Column(name={self._name!r}, values={self._values!r})"

    def to_numeric(self) -> List[Optional[float]]:
        """Return the column parsed as numbers, with ``None`` for misses."""
        return [to_number(value) for value in self._values]

    def to_python(self) -> List[Any]:
        """Return every value, replacing missing tokens with ``None``."""
        return [None if is_missing(value) else value for value in self._values]

    def dropna(self) -> "Column":
        """Return a new column without missing values."""
        return Column(self._name, (v for v in self._values if not is_missing(v)))

    def unique(self) -> List[Any]:
        """Return the distinct non-missing values in first-seen order."""
        seen: List[Any] = []
        for value in self._values:
            if is_missing(value):
                continue
            if value not in seen:
                seen.append(value)
        return seen

    def is_numeric(self) -> bool:
        """Return ``True`` when every non-missing value parses as a number."""
        found = False
        for value in self._values:
            if is_missing(value):
                continue
            if to_number(value) is None:
                return False
            found = True
        return found

    def missing_count(self) -> int:
        return sum(1 for value in self._values if is_missing(value))


class Table:
    """An immutable-by-convention table of headers and rows.

    Cleaning helpers always return *new* :class:`Table` instances rather than
    mutating in place, which makes pipelines easy to reason about.
    """

    def __init__(self, headers: Sequence[str], rows: Iterable[Sequence[Any]]):
        if isinstance(headers, (str, bytes)) or not hasattr(headers, "__iter__"):
            raise TypeError("headers must be a sequence of strings")

        header_list = [self._check_header(h) for h in headers]
        if not header_list:
            raise ValueError("a table must have at least one column")
        if len(set(header_list)) != len(header_list):
            raise ValueError(f"duplicate column names: {header_list}")

        width = len(header_list)
        row_list: List[List[Any]] = []
        for position, row in enumerate(rows):
            if isinstance(row, (str, bytes)) or not hasattr(row, "__iter__"):
                raise TypeError(f"row {position} is not a sequence")
            values = list(row)
            if len(values) != width:
                raise ValueError(
                    f"row {position} has {len(values)} values, expected {width}"
                )
            row_list.append(values)

        self._headers = header_list
        self._rows = row_list

    @staticmethod
    def _check_header(header: Any) -> str:
        if header is None:
            raise ValueError("column names cannot be None")
        name = str(header).strip()
        if not name:
            raise ValueError("column names cannot be empty")
        return name

    @classmethod
    def from_dicts(
        cls, records: Iterable[Mapping[str, Any]], headers: Optional[Sequence[str]] = None
    ) -> "Table":
        """Build a table from an iterable of mappings."""
        records = list(records)
        if headers is None:
            headers = []
            for record in records:
                for key in record:
                    if key not in headers:
                        headers.append(key)
        row_list = [[record.get(header) for header in headers] for record in records]
        return cls(headers, row_list)

    @property
    def headers(self) -> List[str]:
        return list(self._headers)

    @property
    def rows(self) -> List[List[Any]]:
        return [list(row) for row in self._rows]

    @property
    def width(self) -> int:
        return len(self._headers)

    @property
    def height(self) -> int:
        return len(self._rows)

    def __len__(self) -> int:
        return len(self._rows)

    def __iter__(self) -> Iterator[Dict[str, Any]]:
        headers = self._headers
        for row in self._rows:
            yield dict(zip(headers, row))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Table):
            return NotImplemented
        return self._headers == other._headers and self._rows == other._rows

    def __repr__(self) -> str:
        preview = self._rows[:5]
        return f"Table(headers={self._headers!r}, rows={preview!r}, height={len(self)})"

    def __getitem__(self, name: str) -> Column:
        if not isinstance(name, str):
            raise TypeError("column access expects a string name")
        return self.column(name)

    def column(self, name: str) -> Column:
        """Return the named column as a :class:`Column`."""
        try:
            index = self._headers.index(name)
        except ValueError:
            raise ColumnNotFoundError(name) from None
        return Column(name, (row[index] for row in self._rows))

    def has_column(self, name: str) -> bool:
        return name in self._headers

    def to_dicts(self) -> List[Dict[str, Any]]:
        """Return the rows as a list of dictionaries."""
        return list(self)

    def to_rows(self) -> List[List[Any]]:
        return self.rows

    def head(self, n: int = 5) -> "Table":
        return Table(self._headers, self._rows[:n])

    def tail(self, n: int = 5) -> "Table":
        return Table(self._headers, self._rows[-n:] if n > 0 else [])

    def select(self, *columns: str) -> "Table":
        """Return a table containing only *columns*, in the given order."""
        indices = []
        for name in columns:
            try:
                indices.append(self._headers.index(name))
            except ValueError:
                raise ColumnNotFoundError(name) from None
        return Table(list(columns), ([row[i] for i in indices] for row in self._rows))

    def copy(self) -> "Table":
        return Table(self._headers, self._rows)

    def with_column(self, name: str, values: Iterable[Any]) -> "Table":
        """Return a copy with a new column appended."""
        if name in self._headers:
            raise ValueError(f"column already exists: {name!r}")
        values = list(values)
        if len(values) != len(self._rows):
            raise ValueError(
                f"column {name!r} has {len(values)} values, expected {len(self._rows)}"
            )
        headers = self._headers + [self._check_header(name)]
        rows = [row + [value] for row, value in zip(self._rows, values)]
        return Table(headers, rows)

"""Cleaning operations for :mod:`datalab`.

Every function takes a :class:`~datalab.table.Table` and returns a new one;
the input is never modified.
"""

from __future__ import annotations

import statistics
from collections import Counter
from typing import Any, Callable, Iterable, List, Mapping, Optional, Sequence, Union

from .table import Column, Table, is_missing, to_number

__all__ = [
    "strip_whitespace",
    "drop_empty_rows",
    "drop_duplicates",
    "drop_missing",
    "fill_missing",
    "rename_columns",
    "drop_columns",
    "replace_values",
    "convert_types",
    "coerce_numeric",
]


def _resolve(table: Table, columns: Optional[Sequence[str]]) -> List[str]:
    if columns is None:
        return table.headers
    resolved = []
    for name in columns:
        table.column(name)  # raises ColumnNotFoundError for unknown names
        resolved.append(name)
    return resolved


def _rebuild(table: Table, headers: Sequence[str], rows: Iterable[Sequence[Any]]) -> Table:
    return Table(list(headers), rows)


def strip_whitespace(table: Table, columns: Optional[Sequence[str]] = None) -> Table:
    """Trim leading/trailing whitespace from string cells."""
    targets = set(_resolve(table, columns))
    rows = [
        [value.strip() if isinstance(value, str) and name in targets else value
         for name, value in zip(table.headers, row)]
        for row in table.rows
    ]
    return _rebuild(table, table.headers, rows)


def drop_empty_rows(table: Table) -> Table:
    """Drop rows whose cells are all missing."""
    rows = [row for row in table.rows if not all(is_missing(cell) for cell in row)]
    return _rebuild(table, table.headers, rows)


def drop_duplicates(
    table: Table,
    subset: Optional[Sequence[str]] = None,
    *,
    keep: Union[str, bool] = "first",
) -> Table:
    """Drop duplicate rows.

    *keep* may be ``"first"``, ``"last"`` or ``False`` (drop all duplicates).
    """
    if keep not in ("first", "last", False):
        raise ValueError("keep must be 'first', 'last' or False")
    headers = table.headers
    keys = _resolve(table, subset) if subset is not None else headers
    indices = [headers.index(name) for name in keys]

    rows = table.rows
    seen: dict = {}
    for position, row in enumerate(rows):
        signature = tuple(row[i] for i in indices)
        seen.setdefault(signature, []).append(position)

    if keep == "first":
        chosen = {positions[0] for positions in seen.values()}
    elif keep == "last":
        chosen = {positions[-1] for positions in seen.values()}
    else:
        chosen = {positions[0] for positions in seen.values() if len(positions) == 1}
    return _rebuild(table, headers, [row for i, row in enumerate(rows) if i in chosen])


def drop_missing(
    table: Table,
    columns: Optional[Sequence[str]] = None,
    *,
    how: str = "any",
    threshold: Optional[Union[int, float]] = None,
) -> Table:
    """Drop rows containing missing values.

    With ``how="any"`` a row is dropped when *any* selected column is missing;
    with ``how="all"`` only when *every* selected column is missing.  When
    *threshold* is given it overrides *how*: an ``int`` requires that many
    non-missing values, a float in ``(0, 1]`` requires that fraction.
    """
    headers = table.headers
    selected = _resolve(table, columns)
    indices = [headers.index(name) for name in selected]

    if threshold is not None:
        if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
            raise TypeError("threshold must be an int or float")
        if isinstance(threshold, float):
            if not 0 < threshold <= 1:
                raise ValueError("float threshold must be in (0, 1]")
            required = threshold * len(indices)
        else:
            if threshold < 0:
                raise ValueError("int threshold must be non-negative")
            required = threshold
    elif how == "any":
        required = len(indices)
    elif how == "all":
        required = 1
    else:
        raise ValueError("how must be 'any' or 'all'")

    rows = [
        row
        for row in table.rows
        if sum(1 for i in indices if not is_missing(row[i])) >= required
    ]
    return _rebuild(table, headers, rows)


def _fill_value(values: List[Any], strategy: str, fallback: Any) -> Any:
    numbers = [n for n in (to_number(v) for v in values) if n is not None]
    if strategy == "zero":
        return 0
    if strategy == "mean":
        return statistics.fmean(numbers) if numbers else fallback
    if strategy == "median":
        return statistics.median(numbers) if numbers else fallback
    if strategy == "mode":
        present = [v for v in values if not is_missing(v)]
        if not present:
            return fallback
        return Counter(present).most_common(1)[0][0]
    raise ValueError(f"unknown strategy: {strategy!r}")


def fill_missing(
    table: Table,
    value: Any = None,
    *,
    columns: Optional[Sequence[str]] = None,
    strategy: Optional[str] = None,
) -> Table:
    """Replace missing values.

    Use *value* for a constant fill, or *strategy* (``"mean"``, ``"median"``,
    ``"mode"`` or ``"zero"``) to compute a fill per column.
    """
    if strategy is not None and strategy not in ("mean", "median", "mode", "zero"):
        raise ValueError(f"unknown strategy: {strategy!r}")

    headers = table.headers
    targets = set(_resolve(table, columns))
    fills: dict[str, Any] = {}
    for name in targets:
        if strategy is None:
            fills[name] = value
        else:
            column_values = list(table.column(name))
            fills[name] = _fill_value(column_values, strategy, value)

    rows = [
        [fills[name] if name in targets and is_missing(cell) else cell
         for name, cell in zip(headers, row)]
        for row in table.rows
    ]
    return _rebuild(table, headers, rows)


def rename_columns(table: Table, mapping: Mapping[str, str]) -> Table:
    """Return a table with columns renamed according to *mapping*."""
    for name in mapping:
        table.column(name)  # validate source names
    headers = [mapping.get(name, name) for name in table.headers]
    return _rebuild(table, headers, table.rows)


def drop_columns(table: Table, columns: Union[str, Sequence[str]]) -> Table:
    """Return a table without *columns*."""
    if isinstance(columns, str):
        columns = [columns]
    for name in columns:
        table.column(name)  # validate
    drop = set(columns)
    headers = [name for name in table.headers if name not in drop]
    if not headers:
        raise ValueError("cannot drop every column")
    indices = [table.headers.index(name) for name in headers]
    rows = [[row[i] for i in indices] for row in table.rows]
    return _rebuild(table, headers, rows)


def replace_values(
    table: Table,
    replacements: Union[Mapping[Any, Any], Callable[[Any], Any]],
    columns: Optional[Sequence[str]] = None,
) -> Table:
    """Replace cell values, either via a mapping or a callable."""
    headers = table.headers
    targets = set(_resolve(table, columns))

    def convert(cell: Any) -> Any:
        if isinstance(replacements, Mapping):
            return replacements.get(cell, cell)
        return replacements(cell)

    rows = [
        [convert(cell) if name in targets else cell for name, cell in zip(headers, row)]
        for row in table.rows
    ]
    return _rebuild(table, headers, rows)


def convert_types(
    table: Table,
    converters: Mapping[str, Callable[[Any], Any]],
    *,
    on_error: str = "none",
) -> Table:
    """Apply *converters* (column name -> callable) to each cell.

    When a converter raises, *on_error* controls the result: ``"none"`` stores
    ``None``, ``"keep"`` retains the original value and ``"raise"`` re-raises.
    """
    if on_error not in ("none", "keep", "raise"):
        raise ValueError("on_error must be 'none', 'keep' or 'raise'")
    for name in converters:
        table.column(name)  # validate

    headers = table.headers

    def convert(name: str, cell: Any) -> Any:
        converter = converters[name]
        try:
            return converter(cell)
        except (TypeError, ValueError):
            if on_error == "raise":
                raise
            return None if on_error == "none" else cell

    rows = [
        [convert(name, cell) if name in converters else cell
         for name, cell in zip(headers, row)]
        for row in table.rows
    ]
    return _rebuild(table, headers, rows)


def coerce_numeric(table: Table, columns: Optional[Sequence[str]] = None) -> Table:
    """Convert selected columns to numbers, storing ``None`` on failure."""
    targets = _resolve(table, columns)
    return convert_types(table, {name: to_number for name in targets}, on_error="none")

"""Analysis helpers for :mod:`datalab`."""

from __future__ import annotations

import math
import statistics
from collections import Counter
from typing import Any, Callable, Dict, Iterable, List, Mapping, Optional, Sequence, Union

from .table import Column, Table, is_missing, to_number

__all__ = [
    "count",
    "value_counts",
    "numeric_values",
    "mean",
    "median",
    "stdev",
    "quantile",
    "describe",
    "correlation",
    "covariance",
    "group_by",
]


def numeric_values(column: Union[Column, Iterable[Any]]) -> List[float]:
    """Return the finite numeric values of *column*, ignoring missing/invalid."""
    values = column.values if isinstance(column, Column) else list(column)
    numbers: List[float] = []
    for value in values:
        number = to_number(value)
        if number is not None and not math.isinf(number):
            numbers.append(number)
    return numbers


def count(table: Table, column: Optional[str] = None) -> int:
    """Count non-missing values (overall, or within one column)."""
    if column is None:
        return table.height
    return table.column(column).missing_count() and 0 or (
        table.height - table.column(column).missing_count()
    )


def mean(column: Union[Column, Iterable[Any]]) -> Optional[float]:
    numbers = numeric_values(column)
    return statistics.fmean(numbers) if numbers else None


def median(column: Union[Column, Iterable[Any]]) -> Optional[float]:
    numbers = numeric_values(column)
    return statistics.median(numbers) if numbers else None


def stdev(column: Union[Column, Iterable[Any]]) -> Optional[float]:
    numbers = numeric_values(column)
    return statistics.stdev(numbers) if len(numbers) >= 2 else None


def quantile(column: Union[Column, Iterable[Any]], q: float) -> Optional[float]:
    """Return the *q* quantile (0-1) using linear interpolation."""
    if not 0 <= q <= 1:
        raise ValueError("q must be between 0 and 1")
    numbers = sorted(numeric_values(column))
    if not numbers:
        return None
    if len(numbers) == 1:
        return numbers[0]
    position = q * (len(numbers) - 1)
    lower = math.floor(position)
    upper = math.ceil(position)
    if lower == upper:
        return numbers[int(position)]
    fraction = position - lower
    return numbers[lower] * (1 - fraction) + numbers[upper] * fraction


def value_counts(
    table: Table,
    column: str,
    *,
    normalize: bool = False,
    sort: bool = True,
) -> Dict[Any, Union[int, float]]:
    """Count occurrences of each value in *column*."""
    counter = Counter(
        value for value in table.column(column) if not is_missing(value)
    )
    if normalize:
        total = sum(counter.values())
        result: Dict[Any, Union[int, float]] = {
            key: value / total for key, value in counter.items()
        }
    else:
        result = dict(counter)
    if sort:
        return dict(sorted(result.items(), key=lambda item: item[1], reverse=True))
    return result


def describe(
    table: Table, columns: Optional[Sequence[str]] = None
) -> Dict[str, Dict[str, Any]]:
    """Return summary statistics for each requested column.

    Every entry includes ``count``, ``missing`` and ``unique``.  Numeric
    columns additionally report ``mean``, ``median``, ``stdev``, ``min``,
    ``max``, ``q1`` and ``q3``; other columns report ``top`` and ``freq``.
    """
    names = table.headers if columns is None else list(columns)
    summary: Dict[str, Dict[str, Any]] = {}
    for name in names:
        column = table.column(name)
        values = list(column)
        present = [value for value in values if not is_missing(value)]
        stats: Dict[str, Any] = {
            "count": len(present),
            "missing": len(values) - len(present),
            "unique": len(set(present)),
        }
        numbers = numeric_values(values)
        if numbers and len(numbers) == len(present):
            stats.update(
                {
                    "mean": statistics.fmean(numbers),
                    "median": statistics.median(numbers),
                    "stdev": stdev(numbers),
                    "min": min(numbers),
                    "max": max(numbers),
                    "q1": quantile(numbers, 0.25),
                    "q3": quantile(numbers, 0.75),
                }
            )
        elif present:
            top, freq = Counter(present).most_common(1)[0]
            stats.update({"top": top, "freq": freq})
        summary[name] = stats
    return summary


def _numeric_pairs(table: Table, x: str, y: str) -> List[tuple]:
    x_values = list(table.column(x))
    y_values = list(table.column(y))
    pairs = []
    for raw_x, raw_y in zip(x_values, y_values):
        nx, ny = to_number(raw_x), to_number(raw_y)
        if nx is not None and ny is not None:
            pairs.append((nx, ny))
    return pairs


def covariance(table: Table, x: str, y: str) -> Optional[float]:
    """Return the sample covariance of columns *x* and *y*."""
    pairs = _numeric_pairs(table, x, y)
    if len(pairs) < 2:
        return None
    xs = [pair[0] for pair in pairs]
    ys = [pair[1] for pair in pairs]
    mean_x, mean_y = statistics.fmean(xs), statistics.fmean(ys)
    return sum((a - mean_x) * (b - mean_y) for a, b in pairs) / (len(pairs) - 1)


def correlation(table: Table, x: str, y: str) -> Optional[float]:
    """Return the Pearson correlation coefficient of columns *x* and *y*."""
    pairs = _numeric_pairs(table, x, y)
    if len(pairs) < 2:
        return None
    xs = [pair[0] for pair in pairs]
    ys = [pair[1] for pair in pairs]
    mean_x, mean_y = statistics.fmean(xs), statistics.fmean(ys)
    numerator = sum((a - mean_x) * (b - mean_y) for a, b in pairs)
    denom_x = math.sqrt(sum((a - mean_x) ** 2 for a in xs))
    denom_y = math.sqrt(sum((b - mean_y) ** 2 for b in ys))
    if denom_x == 0 or denom_y == 0:
        return None
    return numerator / (denom_x * denom_y)


def _aggregate(values: List[Any], func: Union[str, Callable]) -> Any:
    present = [value for value in values if not is_missing(value)]
    if callable(func):
        return func(present)
    numbers = numeric_values(values)
    if func == "count":
        return len(present)
    if func == "sum":
        return sum(numbers) if numbers else 0
    if func == "mean":
        return statistics.fmean(numbers) if numbers else None
    if func == "median":
        return statistics.median(numbers) if numbers else None
    if func == "stdev":
        return statistics.stdev(numbers) if len(numbers) >= 2 else None
    if func == "min":
        return min(numbers) if numbers else (min(map(str, present)) if present else None)
    if func == "max":
        return max(numbers) if numbers else (max(map(str, present)) if present else None)
    raise ValueError(f"unknown aggregation: {func!r}")


def _agg_name(func: Union[str, Callable]) -> str:
    if isinstance(func, str):
        return func
    return getattr(func, "__name__", "agg")


def group_by(
    table: Table,
    by: Union[str, Sequence[str]],
    aggregations: Mapping[str, Union[str, Callable, Sequence[Union[str, Callable]]]],
) -> Table:
    """Group rows by *by* and aggregate *aggregations*.

    *aggregations* maps a column name (or ``"*"`` for row counts) to one or
    more aggregation names/callables.  Aggregation names are ``sum``, ``mean``,
    ``median``, ``min``, ``max``, ``count`` and ``stdev``.  Result columns are
    named ``<column>_<aggregation>``.

    Example
    -------
    >>> group_by(t, "region", {"sales": ["sum", "mean"], "*": "count"})
    """
    keys = [by] if isinstance(by, str) else list(by)
    for key in keys:
        table.column(key)  # validate group columns

    groups: Dict[tuple, List[List[Any]]] = {}
    order: List[tuple] = []
    key_indices = [table.headers.index(key) for key in keys]
    for row in table.rows:
        signature = tuple(row[i] for i in key_indices)
        if signature not in groups:
            groups[signature] = []
            order.append(signature)
        groups[signature].append(row)

    header_out = list(keys)
    for column, funcs in aggregations.items():
        func_list = [funcs] if isinstance(funcs, (str,)) or callable(funcs) else list(funcs)
        for func in func_list:
            header_out.append(f"{column}_{_agg_name(func)}")

    output_rows: List[List[Any]] = []
    for signature in order:
        rows = groups[signature]
        result = list(signature)
        for column, funcs in aggregations.items():
            func_list = [funcs] if isinstance(funcs, (str,)) or callable(funcs) else list(funcs)
            if column == "*":
                group_values: List[Any] = [None] * len(rows)
            else:
                index = table.headers.index(column)
                group_values = [row[index] for row in rows]
            for func in func_list:
                result.append(_aggregate(group_values, func))
        output_rows.append(result)
    return Table(header_out, output_rows)

